#!/usr/bin/env python3
# This is free and unencumbered software released into the public domain.
#
# Generates `src/tables.rs`, the code page tables, from Python's codecs.
# Run it from the crate root: `python3 -I scripts/tables.py > src/tables.rs`.

PAGES = [437, 720, 737, 775, 850, 852, 855, 857, 858, 860, 861, 862, 863,
         864, 865, 866, 869, 874]

print("""// This is free and unencumbered software released into the public domain.

//! Generated by `scripts/tables.py` from Python's codecs. Do not edit.
//!
//! Each table maps all 256 bytes of a code page to characters, `None` for
//! a byte the code page leaves undefined. The module is declared with
//! `#[rustfmt::skip]`, so that each row keeps four bytes.""")
for page in PAGES:
    print()
    print(f"/// Code page {page}.")
    if page != 437:
        print(f'#[cfg(feature = "cp{page}")]')
    print(f"pub(crate) static CP{page}: [Option<char>; 256] = [")
    for row in range(0, 256, 4):
        cells = []
        for byte in range(row, row + 4):
            try:
                cells.append("Some('\\u{%04X}')" % ord(bytes([byte]).decode(f"cp{page}")))
            except UnicodeDecodeError:
                cells.append("None")
        print("    " + ", ".join(cells) + ",")
    print("];")
